$(document).ready(function () {
    sliderNews2();
    sliderInfo();
    sliderVacancies2();
    sliderTeamInfo();
    sliderLandStages();

    // Menu
    $('.burger').click(function () {
        $('.header__menu').addClass('header__menu--active')
        $('body').addClass('fixed-body')
    })

    $('.burger-close').click(function () {
        $('.header__menu').removeClass('header__menu--active')
        $('body').removeClass('fixed-body')
    })

    $(document).click(function (e) {
        if (
            !$(e.target).closest('.header__menu').length &&
            !$(e.target).closest('.burger').length
        ) {
            $('.header__menu').removeClass('header__menu--active')
            $('body').removeClass('fixed-body')
        }
    })

    // Header
    // $(window).on('scroll', function () {
    //     if ($(window).scrollTop() > 0) {
    //         $('.header').addClass('header--fixed');
    //     } else {
    //         $('.header').removeClass('header--fixed');
    //     }
    // });

    // Pagination
    function setProjectsPaginationWidth() {
        const slider = document.querySelector('.projects2__slider');

        if (!slider) return;

        const pagination = slider.querySelector('.swiper-pagination');

        if (!pagination) return;

        const sliderLeft = slider.getBoundingClientRect().left;

        pagination.style.setProperty(
            '--pagination-width',
            `${window.innerWidth - sliderLeft}px`
        );
    }

    setProjectsPaginationWidth();

    window.addEventListener('resize', setProjectsPaginationWidth);

    // Accordion
    $(".item-show").click(function () {
        const $this = $(this);
        const $content = $this.siblings(".item-hidden");

        $(".item-show").not($this).removeClass("item-show--active");
        $(".item-hidden").not($content).slideUp();

        $this.toggleClass("item-show--active");
        $content.slideToggle();
    });
})

// Animation
gsap.registerPlugin(ScrollTrigger);

// Info
if (window.innerWidth >= 993) {
    function headerFixed() {
        if ($(window).scrollTop() > 0 && !infoActive) {
            $('.header').addClass('header--fixed');
        } else {
            $('.header').removeClass('header--fixed');
        }
    }

    let infoActive = false;

    $(window).on('scroll', function () {
        headerFixed();
    });

    headerFixed();

    function infoHorizontalScroll() {

        const info = document.querySelector('.info');
        const slider = document.querySelector('.info__slider');
        const slides = gsap.utils.toArray('.info-slide');
        const progress = document.querySelector('.info__pagination-progress');

        if (!info || !slider || !slides.length) return;

        const getDistance = () => {
            const lastSlide = slides[slides.length - 1];

            if (window.innerWidth <= 1400) {
                return (
                    lastSlide.offsetLeft +
                    lastSlide.offsetWidth -
                    window.innerWidth
                );
            }

            return lastSlide.offsetLeft;
        };

        gsap.to(slider, {

            x: () => -getDistance(),

            ease: 'none',

            scrollTrigger: {

                trigger: info,

                start: 'top top',

                end: () => `+=${getDistance()}`,

                pin: true,

                scrub: 1,

                invalidateOnRefresh: true,

                anticipatePin: 1,

                onUpdate: (self) => {
                    if (progress) {
                        gsap.set(progress, {
                            scaleX: self.progress
                        });
                    }
                },

                onEnter: () => {
                    infoActive = true;
                    $('.header').removeClass('header--fixed');
                },

                onLeave: () => {
                    infoActive = false;
                    headerFixed();
                },

                onEnterBack: () => {
                    infoActive = true;
                    $('.header').removeClass('header--fixed');
                },

                onLeaveBack: () => {
                    infoActive = false;
                    headerFixed();
                }
            }
        });
    }

    infoHorizontalScroll();

    $(window).on('load', function () {
        ScrollTrigger.refresh();
    });
}

// Projects
const projectsTl = gsap.timeline({
    scrollTrigger: {
        trigger: ".projects",
        start: window.innerWidth <= 992 ? "top 100px" : "top 150px",
        toggleActions: "play none none none",
    }
});

projectsTl
    .from(".projects__title", {
        yPercent: 100,
        duration: 1.6,
        ease: "power3.out",
    })
