// Universal code
gsap.utils.toArray(".fade-group").forEach((group) => {
    const items = group.querySelectorAll(".fade-down");

    const tl = gsap.timeline({
        scrollTrigger: {
            trigger: group,
            start: "top 85%",
            toggleActions: "play none none none"
        }
    });

    items.forEach((item) => {
        tl.fromTo(
            item,
            {
                yPercent: -30,
                opacity: 0
            },
            {
                yPercent: 0,
                opacity: 1,
                duration: 0.8,
                ease: "power2.out"
            }
        );
    });
});